    "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Ghost Todo on a canvas — F# widgets as WebAssembly GC</title>\n  <style>\n    :root { color-scheme: dark; }\n    html, body { height: 100%; margin: 0; background: #0f172a; }\n    /* the whole page is the canvas: the module draws the card, the fields and the buttons */\n    #gfx { display: block; width: 100%; height: 100%; outline: none; touch-action: none; }\n    #status { position: fixed; left: 1rem; bottom: 1rem; margin: 0; font: 14px/1.4 system-ui, sans-serif; color: #94a3b8; }\n    #status:empty { display: none; }\n    noscript { position: fixed; inset: 1rem; font: 16px system-ui, sans-serif; color: #f1f5f9; }\n  </style>\n</head>\n<body>\n  <canvas id=\"gfx\" tabindex=\"0\" role=\"application\" aria-label=\"Ghost Todo: a todo list drawn on a canvas. Tab moves between the field and the buttons, Enter adds.\"></canvas>\n  <p id=\"status\">Loading…</p>\n  <noscript>This page runs a WebAssembly module and needs JavaScript.</noscript>\n  <!-- This page is served at <host>/canvas/ and talks to the API of the same host (../api/…).  ?room=NAME picks a room, ?api=https://host/ another API (the module answers CORS). -->\n  <script type=\"module\">\n    import { boot } from \"./runtime/boot.js\";\n    import { mount } from \"./runtime/gfx.js\";\n\n    const instance = await boot({ wasm: new URL(\"GhostTodoCanvas.wasm\", import.meta.url), entry: \"start\" });\n    if (instance) {\n      mount(instance, \"gfx\");\n      document.getElementById(\"status\").textContent = \"\";     // the status is for errors; a module that runs needs no banner\n      document.getElementById(\"gfx\").focus();                // type at once\n    }\n  </script>\n</body>\n</html>\n"
